      }

      .hero-copy,
      .hero-panel,
      .section-card,
      .product-card,
      .deal-card,
      .story-card,
      .newsletter {
        background: linear-gradient(180deg, #141c37 0%, #0f1730 100%);
        border: 1px solid var(--border);
        box-shadow: var(--shadow);
      }

      .hero-copy,
      .hero-panel {
        border-radius: var(--radius-xl);
        overflow: hidden;
      }

      .hero-copy {
        padding: clamp(2rem, 4vw, 4rem);
        position: relative;
