      }

      .hero-copy::after {
        content: "";
        position: absolute;
        inset: auto -10% -30% auto;
        width: 18rem;
        height: 18rem;
        border-radius: 50%;
        background: radial-gradient(circle, #9d7cff55 0%, #9d7cff00 70%);
        z-index: -1;
      }

      .eyebrow {
        display: inline-flex;
        align-items: center;
        gap: 0.5rem;
        margin-bottom: 1rem;
        padding: 0.35rem 0.85rem;
        border-radius: 999px;
        background: #1b2549;
        color: #d5ddff;
        font-size: 0.94rem;
        font-weight: 700;
      }

      h1,
      h2,
      h3 {
        margin: 0;
        line-height: 1.08;
      }

      h1 {
        max-width: 11ch;
        font-size: clamp(2.5rem, 6vw, 5.3rem);
        letter-spacing: -0.04em;
      }

      .hero-copy p,
      .section-header p,
      .story-copy p,
      .deal-card p,
      .product-copy p,
      .newsletter p {
        color: var(--muted);
      }

      .hero-actions {
        display: flex;
        flex-wrap: wrap;
        gap: 0.9rem;
        margin: 1.7rem 0 2rem;
      }

      .metrics {
        display: grid;
        grid-template-columns: repeat(3, minmax(0, 1fr));
        gap: 0.9rem;
      }

      .metric {
        padding: 1rem;
        border-radius: var(--radius-md);
        background: #0c142b;
        border: 1px solid #233056;
      }

      .metric strong {
        display: block;
        margin-bottom: 0.25rem;
        font-size: 1.3rem;
      }

      .hero-panel {
        display: grid;
        gap: 1rem;
        padding: 1.2rem;
      }

      .panel-visual {
        min-height: 16rem;
        border-radius: 1.5rem;
        background:
          radial-gradient(circle at 20% 25%, #ffe8a2 0%, #ffc857 22%, transparent 24%),
          radial-gradient(circle at 62% 32%, #f4f7fb 0%, #9cb2ff 13%, transparent 15%),
          radial-gradient(circle at 65% 70%, #9d7cff 0%, #7c98ff 16%, transparent 18%),
          linear-gradient(135deg, #151f42 0%, #0a1227 100%);
        position: relative;
        overflow: hidden;
      }

      .panel-visual::before,
      .panel-visual::after {
        content: "";
        position: absolute;
        border-radius: 50%;
        border: 1px solid #ffffff24;
      }

      .panel-visual::before {
        width: 22rem;
        height: 22rem;
        top: -8rem;
        right: -8rem;
      }

      .panel-visual::after {
        width: 12rem;
        height: 12rem;
        bottom: -4rem;
        left: -4rem;
      }

      .hero-panel-copy {
        display: grid;
        gap: 0.7rem;
        padding: 0.5rem 0.4rem 0.2rem;
      }

      .hero-panel-copy strong {
        font-size: 1.35rem;
      }

      .page-section {
        padding: 1.35rem 0;
      }

      .section-header {
        display: flex;
        flex-wrap: wrap;
        align-items: end;
        justify-content: space-between;
        gap: 1rem;
        margin-bottom: 1.1rem;
      }

      .section-header h2 {
        font-size: clamp(1.8rem, 3vw, 2.5rem);
        letter-spacing: -0.03em;
      }

      .featured-grid,
      .deal-grid,
      .stories-grid {
        display: grid;
        gap: 1rem;
      }

      .featured-grid {
        grid-template-columns: repeat(3, minmax(0, 1fr));
      }

      .deal-grid {
        grid-template-columns: repeat(2, minmax(0, 1fr));
      }

      .stories-grid {
        grid-template-columns: repeat(3, minmax(0, 1fr));
      }

      .product-card,
      .deal-card,
      .story-card,
      .newsletter {
        border-radius: var(--radius-lg);
        overflow: hidden;
      }

      .product-art,
      .story-art {
        min-height: 14rem;
        border-bottom: 1px solid #2a345a;
      }

      .product-art {
        background: var(--art-background, linear-gradient(135deg, #283765 0%, #0d1430 100%));
      }

      .story-art {
        background: var(--story-background, linear-gradient(135deg, #4b276b 0%, #121931 100%));
      }

      .product-copy,
      .deal-copy,
      .story-copy,
      .newsletter-copy {
        padding: 1.35rem;
      }

      .pill-row {
