        flex-wrap: wrap;
        gap: 0.55rem;
        margin-bottom: 0.9rem;
      }

      .pill {
        display: inline-flex;
        align-items: center;
        gap: 0.4rem;
        padding: 0.35rem 0.75rem;
        border-radius: 999px;
        background: #1b2446;
        border: 1px solid #2e3b67;
        color: #d8def6;
        font-size: 0.88rem;
      }

      .price-row,
      .deal-meta {
        display: flex;
        align-items: center;
        justify-content: space-between;
        gap: 1rem;
        margin-top: 1rem;
      }

      .price {
        font-size: 1.4rem;
        font-weight: 800;
      }

      .deal-card {
        display: grid;
        grid-template-columns: minmax(0, 1fr) auto;
        align-items: stretch;
      }

      .deal-copy {
        display: grid;
        gap: 0.65rem;
      }

      .deal-highlight {
        min-width: 10rem;
        display: grid;
        place-items: center;
        padding: 1.25rem;
        border-left: 1px solid #2a345a;
        background: linear-gradient(180deg, #1a2547 0%, #101833 100%);
      }

      .deal-highlight strong {
        font-size: 2rem;
        color: var(--accent-warm);
      }

      .story-card {
        display: grid;
        grid-template-rows: auto 1fr;
      }

      .kicker {
        color: #d9e1ff;
        font-weight: 700;
        font-size: 0.92rem;
        text-transform: uppercase;
        letter-spacing: 0.08em;
      }

      .newsletter {
        margin: 2rem 0 4rem;
        display: grid;
        grid-template-columns: minmax(0, 1fr) minmax(280px, 0.95fr);
      }

      .newsletter-copy {
        padding: clamp(1.5rem, 4vw, 2.25rem);
      }

      .newsletter form {
        display: grid;
        gap: 0.8rem;
        margin-top: 1.2rem;
      }

      .field-row {
        display: flex;
        gap: 0.8rem;
      }

      label {
        font-weight: 700;
      }

      input[type="email"] {
        width: 100%;
        min-width: 0;
        min-height: 3rem;
        padding: 0.85rem 1rem;
        color: var(--text);
        background: #0a1227;
        border: 1px solid #31416e;
        border-radius: 999px;
      }

      .helper-text,
      .status-text,
      .footer-copy {
        color: var(--muted);
        font-size: 0.94rem;
      }

      .status-text {
        min-height: 1.5rem;
      }

      .section-card {
        border-radius: var(--radius-xl);
        padding: 1.5rem;
      }

      .site-footer {
        padding: 0 0 2.5rem;
      }

      .footer-grid {
        display: flex;
        flex-wrap: wrap;
        justify-content: space-between;
        gap: 1rem;
        padding-top: 1.5rem;
        border-top: 1px solid #242e52;
      }

      @media (max-width: 980px) {
        .hero-grid,
        .newsletter,
        .featured-grid,
        .stories-grid,
        .deal-grid {
          grid-template-columns: 1fr;
        }

        .deal-card {
          grid-template-columns: 1fr;
        }

        .deal-highlight {
          border-left: 0;
          border-top: 1px solid #2a345a;
          min-width: 0;
        }
      }

      @media (max-width: 720px) {
        .top-bar,
        .nav-bar,
        .field-row,
        .metrics {
          grid-template-columns: 1fr;
          flex-direction: column;
          align-items: stretch;
        }

        .metrics {
          display: grid;
        }

        .nav-bar {
          align-items: flex-start;
        }
      }

      @media (max-width: 480px) {
        .container {
          width: min(calc(100% - 1rem), var(--container));
        }

        .hero {
          padding-top: 2rem;
        }

        .hero-copy,
        .hero-panel,
        .product-copy,
        .deal-copy,
        .story-copy,
        .newsletter-copy {
          padding-left: 1rem;
          padding-right: 1rem;
        }

        .price-row,
        .deal-meta {
          align-items: flex-start;
          flex-direction: column;
        }
      }

      @media (prefers-reduced-motion: reduce) {
        html {
          scroll-behavior: auto;
        }

        *,
        *::before,
        *::after {
          transition: none !important;
          animation: none !important;
        }
      }

      @media (forced-colors: active) {
        :root {
          --bg: Canvas;
          --panel: Canvas;
          --panel-strong: Canvas;
          --panel-alt: Canvas;
          --text: CanvasText;
          --muted: CanvasText;
          --border: ButtonBorder;
          --accent: LinkText;
          --accent-strong: LinkText;
          --accent-warm: Highlight;
        }

        body,
        .hero-copy,
        .hero-panel,
        .product-card,
        .deal-card,
        .story-card,
        .newsletter,
        .metric,
        .button,
        .button-secondary,
        .pill,
        input[type="email"] {
          background: Canvas;
          color: CanvasText;
          border-color: ButtonBorder;
          box-shadow: none;
        }

        .button,
        .button-secondary {
          outline: 2px solid transparent;
        }
      }
    </style>
  </head>
  <body>
    <a class="skip-link" href="#main-content">Skip to main content</a>
    <div id="app" class="page-shell"></div>
    <script>
      const featuredProducts = [
        {
          name: "Lumen Carryall",
          category: "Featured product",
          description: "Weather-ready recycled nylon tote with modular interior sleeves for commute, travel, and everyday carry.",
          price: "$148",
          badge: "Best seller",
          art: "linear-gradient(135deg, #31406f 0%, #0d1430 100%)",
          cta: "Shop Lumen Carryall"
        },
        {
          name: "Halo Table Lamp",
          category: "New arrival",
          description: "Dimmable ambient lamp in smoked glass and brushed alloy for a softer after-hours workspace.",
          price: "$96",
          badge: "Studio pick",
          art: "linear-gradient(135deg, #62458d 0%, #171d3a 100%)",
          cta: "Shop Halo Table Lamp"
        },
        {
          name: "Aster Knit Set",
          category: "Seasonal edit",
          description: "Soft-structure lounge layers cut for movement, finished in graphite tones with premium rib texture.",
          price: "$122",
          badge: "Limited drop",
          art: "linear-gradient(135deg, #6a5530 0%, #171d3a 100%)",
          cta: "Shop Aster Knit Set"
        }
      ];

      const deals = [
        {
          title: "Midnight Member Event",
          description: "Extra savings across lounge, home, and tech accessories when you bundle three or more essentials.",
          detail: "Use code MIDNIGHT",
          savings: "25% off"
        },
        {
          title: "Weekend Design Bundle",
          description: "Pair editorial favorites with a warm-light home setup and unlock free two-day delivery at checkout.",
          detail: "Ends Sunday",
          savings: "Free shipping"
        }
      ];

      const stories = [
        {
          kicker: "Editorial",
          title: "The after-dark apartment edit",
          description: "A room-by-room guide to layering texture, lighting, and storage for a polished nighttime routine.",
          linkText: "Read the apartment edit",
          art: "linear-gradient(135deg, #3f205d 0%, #121931 100%)"
        },
        {
          kicker: "Journal",
          title: "Five pieces that sharpen your commute",
          description: "Compact upgrades for motion-friendly days, from weatherproof totes to modular desk kits.",
          linkText: "Read the commute guide",
          art: "linear-gradient(135deg, #223d73 0%, #121931 100%)"
        },
        {
          kicker: "How to style",
          title: "Layering neutrals with contrast",
          description: "Build depth with charcoal, slate, and warm metallic accents that work from home to evening plans.",
          linkText: "Read the styling guide",
          art: "linear-gradient(135deg, #5a4328 0%, #121931 100%)"
        }
      ];

      const createProductCard = (product) => `
        <article class="product-card">
          <div class="product-art" style="--art-background: ${product.art};" aria-hidden="true"></div>
          <div class="product-copy">
            <div class="pill-row">
              <span class="pill">${product.category}</span>
              <span class="pill">${product.badge}</span>
            </div>
            <h3>${product.name}</h3>
            <p>${product.description}</p>
            <div class="price-row">
              <span class="price">${product.price}</span>
              <a class="button-secondary" href="#newsletter" aria-label="${product.cta}">
                Shop now
              </a>
            </div>
          </div>
        </article>
      `;

      const createDealCard = (deal) => `
        <article class="deal-card">
          <div class="deal-copy">
            <span class="kicker">Deal</span>
            <h3>${deal.title}</h3>
            <p>${deal.description}</p>
            <div class="deal-meta">
              <span class="pill">${deal.detail}</span>
              <a class="button-secondary" href="#featured-products" aria-label="Browse products for ${deal.title}">
                Browse products
              </a>
            </div>
          </div>
          <div class="deal-highlight">
            <div>
              <span class="kicker">Savings</span>
              <strong>${deal.savings}</strong>
            </div>
          </div>
        </article>
      `;

      const createStoryCard = (story) => `
        <article class="story-card">
          <div class="story-art" style="--story-background: ${story.art};" aria-hidden="true"></div>
          <div class="story-copy">
            <span class="kicker">${story.kicker}</span>
            <h3>${story.title}</h3>
            <p>${story.description}</p>
            <a class="button-secondary" href="#newsletter" aria-label="${story.linkText}">
              ${story.linkText}
            </a>
          </div>
        </article>
      `;

      const Header = () => `
        <header class="site-header">
          <div class="container top-bar">
            <span>Free delivery on orders over $100</span>
            <nav aria-label="Utility">
              <ul class="utility-links">
                <li><a class="utility-link" href="#deals">Deals</a></li>
                <li><a class="utility-link" href="#editorial">Editorial</a></li>
                <li><a class="utility-link" href="#newsletter">Join the list</a></li>
              </ul>
            </nav>
          </div>
          <div class="container nav-bar">
            <a class="brand" href="#" aria-label="Nocturne Supply home">
              <span class="brand-mark" aria-hidden="true"></span>
              <span>Nocturne Supply</span>
            </a>
            <nav aria-label="Primary">
              <ul class="nav-links">
                <li><a class="nav-link" href="#featured-products">Featured</a></li>
                <li><a class="nav-link" href="#deals">Deals</a></li>
                <li><a class="nav-link" href="#editorial">Stories</a></li>
              </ul>
            </nav>
          </div>
        </header>
      `;

      const Hero = () => `
        <section class="hero">
          <div class="container hero-grid">
            <div class="hero-copy section-card">
              <span class="eyebrow">Curated for evenings that move</span>
              <h1>Design-forward essentials for every kind of night.</h1>
              <p>
                Discover considered retail drops across home, wardrobe, and carry goods with a cinematic dark aesthetic and
                elevated utility.
              </p>
              <div class="hero-actions">
                <a class="button" href="#featured-products">Shop featured</a>
                <a class="button-secondary" href="#editorial">Explore stories</a>
              </div>
              <div class="metrics" aria-label="Brand highlights">
                <div class="metric">
                  <strong>42</strong>
                  <span>fresh arrivals this week</span>
                </div>
                <div class="metric">
                  <strong>4.8/5</strong>
                  <span>average community rating</span>
                </div>
                <div class="metric">
                  <strong>24h</strong>
                  <span>dispatch on top picks</span>
                </div>
              </div>
            </div>
            <aside class="hero-panel" aria-label="Seasonal spotlight">
              <div class="panel-visual"></div>
              <div class="hero-panel-copy">
                <span class="kicker">Seasonal spotlight</span>
                <strong>The Night Shift collection</strong>
                <p>Low-glare lighting, layered knits, and modular storage designed to make small spaces feel intentional.</p>
                <a class="button-secondary" href="#deals">See current offers</a>
              </div>
            </aside>
          </div>
        </section>
      `;

      const FeaturedSection = () => `
        <section class="page-section" id="featured-products" aria-labelledby="featured-heading">
          <div class="container">
            <div class="section-header">
              <div>
                <h2 id="featured-heading">Featured products</h2>
                <p>Sharp silhouettes, practical details, and premium finishes selected from the newest collection.</p>
              </div>
              <a class="button-secondary" href="#newsletter">Get launch updates</a>
            </div>
            <div class="featured-grid">
              ${featuredProducts.map(createProductCard).join("")}
            </div>
          </div>
        </section>
      `;

      const DealsSection = () => `
        <section class="page-section" id="deals" aria-labelledby="deals-heading">
          <div class="container">
            <div class="section-header">
              <div>
                <h2 id="deals-heading">Deals worth opening the app for</h2>
                <p>Timed savings and loyalty perks built around the products readers and shoppers revisit most.</p>
              </div>
            </div>
            <div class="deal-grid">
              ${deals.map(createDealCard).join("")}
            </div>
          </div>
        </section>
      `;

      const EditorialSection = () => `
        <section class="page-section" id="editorial" aria-labelledby="editorial-heading">
          <div class="container">
            <div class="section-header">
              <div>
                <h2 id="editorial-heading">Editorial content</h2>
                <p>Commerce meets storytelling with guides, seasonal edits, and practical inspiration from the brand studio.</p>
              </div>
            </div>
            <div class="stories-grid">
              ${stories.map(createStoryCard).join("")}
            </div>
          </div>
        </section>
      `;

      const NewsletterSection = () => `
        <section class="container" id="newsletter" aria-labelledby="newsletter-heading">
          <div class="newsletter">
            <div class="newsletter-copy">
              <span class="eyebrow">Stay in the loop</span>
              <h2 id="newsletter-heading">Get drop alerts, editorial picks, and private offer access.</h2>
              <p>Weekly notes from Nocturne Supply with early product previews and inspiration for home, carry, and wardrobe.</p>
            </div>
            <div class="newsletter-copy">
              <form id="newsletter-form" novalidate>
                <label for="email">Email address <span aria-hidden="true">*</span></label>
                <div class="field-row">
                  <input
                    id="email"
                    name="email"
                    type="email"
                    autocomplete="email"
                    required
                    aria-required="true"
                    aria-describedby="email-help email-status"
                  />
                  <button class="button" type="submit">Join now</button>
                </div>
                <p class="helper-text" id="email-help">Required. We send one curated update each week.</p>
                <p class="status-text" id="email-status" aria-live="polite"></p>
              </form>
            </div>
          </div>
        </section>
      `;

      const Footer = () => `
        <footer class="site-footer">
          <div class="container footer-grid">
            <p class="footer-copy">Nocturne Supply builds elevated essentials with a focus on utility, texture, and modern retail storytelling.</p>
            <nav aria-label="Footer">
              <ul class="utility-links">
                <li><a class="utility-link" href="#featured-products">Shop</a></li>
                <li><a class="utility-link" href="#editorial">Journal</a></li>
                <li><a class="utility-link" href="#newsletter">Newsletter</a></li>
              </ul>
            </nav>
          </div>
        </footer>
      `;

      const App = () => `
        ${Header()}
        <main id="main-content" tabindex="-1">
          ${Hero()}
          ${FeaturedSection()}
          ${DealsSection()}
          ${EditorialSection()}
          ${NewsletterSection()}
        </main>
        ${Footer()}
      `;

      const root = document.getElementById("app");
      root.innerHTML = App();

      const newsletterForm = document.getElementById("newsletter-form");
      const emailInput = document.getElementById("email");
      const emailStatus = document.getElementById("email-status");

      newsletterForm.addEventListener("submit", (event) => {
        event.preventDefault();
